    width: 25px;
    margin-right: 25px;
}
.nav-right .user-icon {
    width: 35px;
    border-radius: 50%;
    margin-right: 0;
}
.nav-left .menu-icon {
    width: 22px;
    margin-right: 25px;
}
.nav-left .logo {
    width: 130px;
}
